import axios, { AxiosResponse, AxiosInstance, AxiosError, CancelTokenSource } from 'axios';
import { noop } from '@game-studio/utilities';
import { IServerCommand, IServerResponse, ConnectionState, ILongPollingConnectionOptions } from '../types';
import { RealtimeServer } from './server';

const TIMEOUT = 60000;
const EMPTY_COMMAND: IServerCommand = {
    toPayload() {
        return 'none';
    }
};

export class LongPollingConnection {
    public proxyUrl: string;
    public serverUrl: string;
    public messageNo: number;
    public requestNo: number;
    public sessionGuid?: string;
    public connected: boolean;
    public isDisconnecting: boolean;
    public isPolling: boolean;
    public commandQueue: IServerCommand[];
    public activeRequest?: Promise<void>;
    public http: AxiosInstance;
    public source: CancelTokenSource;
    private server: RealtimeServer;

    constructor(server: RealtimeServer, options: ILongPollingConnectionOptions) {
        this.server = server;
        this.proxyUrl = options.proxyUrl;
        this.serverUrl = options.serverUrl;
        this.messageNo = 0;
        this.requestNo = 0;
        this.isDisconnecting = false;
        this.isPolling = false;
        this.commandQueue = [];
        this.http = axios.create({
            baseURL: this.proxyUrl,
            timeout: TIMEOUT,
            withCredentials: true
        });
    }

    public connect(): Promise<void> {
        if (this.connected) {
            return Promise.resolve();
        }

        this.broadcastNewConnectionState(ConnectionState.CONNECTING);

        return this.http.get(`/connect?server=${this.serverUrl}`)
            .then((response: AxiosResponse) => this.onConnected(response))
            .catch((e: AxiosError) => this.onErrorResponse(e));
    }

    public disconnect(force: boolean = false): Promise<void> {
        if (!this.connected) {
            return Promise.resolve();
        }

        if (this.activeRequest) {
            this.source.cancel();
        }

        this.isDisconnecting = true;
        this.broadcastNewConnectionState(ConnectionState.DISCONNECTING);

        if (force) {
            return Promise.resolve(this.onDisconnected());
        }

        return this.activeRequest = this.http.get(`/disconnect?id=${this.sessionGuid}`)
            .then(() => this.onDisconnected())
            .catch((e: AxiosError) => this.onErrorResponse(e));
    }

    public send(command?: IServerCommand) {
        if (command) {
            this.commandQueue.push(command);
        }

        if (this.activeRequest && this.isPolling) {
            this.source.cancel();
            this.activeRequest = void 0;
            this.isPolling = false;
        }

        if (this.activeRequest) {
            return;
        }

        return this.processQueue();
    }

    public destroy(): void {
        this.disconnect(true);
    }

    // long-polling has no persistent socket to auto-reconnect, so these are no-ops
    public get isReconnecting(): boolean {
        return false;
    }

    public enableAutoReconnect(): void {
        /* not supported for long-polling */
    }

    public disableAutoReconnect(): void {
        /* not supported for long-polling */
    }

    public pauseReconnect(): void {
        /* not supported for long-polling */
    }

    public resumeReconnect(): void {
        /* not supported for long-polling */
    }

    private processQueue() {
        let message: IServerCommand;

        if (this.commandQueue.length > 0) {
            message = this.commandQueue.shift() as IServerCommand;
        } else {
            message = EMPTY_COMMAND;
            this.isPolling = true;
        }

        this.source = axios.CancelToken.source();

        return this.activeRequest = this.http
            .post(`/send?id=${this.sessionGuid}&message=${this.messageNo}&reqno=${this.requestNo}`, message.toPayload(), {
                cancelToken: this.source.token
            })
            .then((response: AxiosResponse) => this.onProcessQueueRequestEnd(response))
            .catch((e: AxiosError) => this.onErrorResponse(e))
            .catch(noop);
    }

    private onConnected(response: AxiosResponse) {
        this.activeRequest = void 0;
        this.sessionGuid = response.data.guid;
        this.messageNo = 0;
        this.requestNo = 0;
        this.isDisconnecting = false;
        this.commandQueue = [];
        this.broadcastNewConnectionState(ConnectionState.CONNECTED);
        this.send();
    }

    private onDisconnected() {
        this.activeRequest = void 0;
        this.sessionGuid = void 0;
        this.messageNo = 0;
        this.requestNo = 0;
        this.isDisconnecting = false;
        this.commandQueue = [];
        this.broadcastNewConnectionState(ConnectionState.DISCONNECTED);
    }

    private onErrorResponse(error: AxiosError) {
        if (axios.isCancel(error)) {
            if (!this.isDisconnecting) {
                this.send();
            }

            return Promise.resolve();
        }

        this.server.emit('error', error);
        return Promise.reject(error);
    }

    private onProcessQueueRequestEnd(response: AxiosResponse) {
        this.activeRequest = void 0;
        this.isPolling = false;

        const responses: IServerResponse[] = Array.isArray(response.data) ? response.data : [response.data];

        responses.forEach(this.handleResponse, this);

        if (this.connected) {
            this.send();
        }
    }

    private handleResponse(response: IServerResponse) {
        this.messageNo = response.Number ? response.Number : this.messageNo;
        this.requestNo++;
        this.server.emit('response', response);
    }

    private broadcastNewConnectionState(state: ConnectionState) {
        this.server.emit('state', state);
    }
}
